package com.gymmind.membership.application; import com.gymmind.membership.domain.model.MembershipPackage; import java.math.BigDecimal; public record MembershipPackageView(Long id,Long tenantId,String name,String entitlementType,Integer entitlementCount,Integer validDays,BigDecimal price,String currency,boolean active){public static MembershipPackageView from(MembershipPackage p){return new MembershipPackageView(p.getId(),p.getTenantId(),p.getName(),p.getEntitlementType(),p.getEntitlementCount(),p.getValidDays(),p.getPrice(),p.getCurrency(),p.isActive());}}
